package com.mukasanches.zapptv.playback

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

class PlaybackRecoveryPolicyTest {
    @Test
    fun sanitizesAndDeduplicatesCandidates() {
        val result = PlaybackRecoveryPolicy.sanitize(
            listOf(" https://a.test/live.m3u8 ", "ftp://bad", "https://a.test/live.m3u8", "http://b.test/live")
        )
        assertEquals(listOf("https://a.test/live.m3u8", "http://b.test/live"), result)
    }

    @Test
    fun movesOnlyWithinBounds() {
        assertEquals(1, PlaybackRecoveryPolicy.nextCandidate(0, 2))
        assertNull(PlaybackRecoveryPolicy.nextCandidate(1, 2))
    }

    @Test
    fun retryDelayIsBounded() {
        assertEquals(1000L, PlaybackRecoveryPolicy.retryDelay(0))
        assertEquals(2000L, PlaybackRecoveryPolicy.retryDelay(1))
        assertEquals(8000L, PlaybackRecoveryPolicy.retryDelay(10))
    }
}

package com.mukasanches.zapptv.vod

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

class InfiniteCinemaCoreTest {
    @Test
    fun publicDomainIsRecognized() {
        assertEquals(
            RightsStatus.PUBLIC_DOMAIN,
            CinemaRightsEngine.classify(
                "Internet Archive",
                "Public Domain",
                null
            )
        )
    }

    @Test
    fun creativeCommonsAttributionIsRecognized() {
        assertEquals(
            RightsStatus.ATTRIBUTION_REQUIRED,
            CinemaRightsEngine.classify(
                "Europeana",
                "CC BY 4.0",
                "https://creativecommons.org/licenses/by/4.0/"
            )
        )
    }

    @Test
    fun sameMovieAcrossProvidersMerges() {
        val a = VodItem(
            id = "a",
            title = "The General",
            year = "1926",
            source = "Provider A",
            playbackUrl = "https://example.org/a.mp4",
            rightsStatus = RightsStatus.PUBLIC_DOMAIN
        )
        val b = VodItem(
            id = "b",
            title = "General, The",
            year = "1926",
            source = "Provider B",
            posterUrl = "https://example.org/poster.jpg",
            rightsStatus = RightsStatus.PUBLIC_DOMAIN
        )

        val merged = MovieIdentityResolver.merge(listOf(a, b))
        assertEquals(1, merged.size)
        assertTrue(merged.first().providers.contains("Provider A"))
        assertTrue(merged.first().providers.contains("Provider B"))
        assertEquals("https://example.org/poster.jpg", merged.first().posterUrl)
    }

    @Test
    fun yearNormalizerExtractsValidYear() {
        assertEquals(
            "1969",
            CinemaMetadataNormalizer.year("1969-07-20T20:17:00Z")
        )
    }

    @Test
    fun unknownRightsDoNotAutoPlayByDefault() {
        val item = VodItem(
            id = "x",
            title = "Unknown",
            source = "Unknown Provider"
        )
        assertFalse(CinemaRightsEngine.canAutoPlay(item))
    }

    @Test
    fun subtitleSupportAcceptsXmlTtml() {
        assertTrue(VodSubtitleSupport.isSupportedFile("captions.xml"))
        assertEquals(
            "application/ttml+xml",
            VodSubtitleSupport.fromUrl("https://example.org/captions.xml")?.mimeType
        )
    }

    @Test
    fun subtitleOrderingKeepsPortugueseBeforeEnglishAndSpanish() {
        val ordered = VodSubtitleSupport.preferPortuguese(
            listOf(
                VodSubtitle("https://x/es.vtt", "es", "Español", "text/vtt"),
                VodSubtitle("https://x/en.vtt", "en", "English", "text/vtt"),
                VodSubtitle("https://x/pt.vtt", "pt-BR", "Português", "text/vtt")
            )
        )
        assertEquals(listOf("pt-BR", "en", "es"), ordered.map { it.language })
    }
}

package com.mukasanches.zapptv.vod

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

class VodSubtitleSupportTest {
    @Test
    fun mapsPortugueseBrazilSrt() {
        val subtitle = VodSubtitleSupport.fromUrl(
            "https://example.org/movie.pt-BR.srt"
        )
        requireNotNull(subtitle)
        assertEquals("pt-BR", subtitle.language)
        assertEquals("application/x-subrip", subtitle.mimeType)
        assertTrue(subtitle.isDefault)
    }

    @Test
    fun supportsVttAndTtml() {
        assertTrue(VodSubtitleSupport.isSupportedFile("movie.vtt"))
        assertTrue(VodSubtitleSupport.isSupportedFile("movie.ttml"))
    }

    @Test
    fun deduplicatesSameMovieAcrossCatalogs() {
        val items = listOf(
            VodItem(id = "a", title = "Night of the Living Dead", year = "1968"),
            VodItem(id = "b", title = "Night-of-the-Living-Dead", year = "1968")
        )
        assertEquals(1, MovieCatalogDeduplicator.deduplicate(items).size)
    }

    @Test
    fun portugueseSubtitlesSortFirst() {
        val subtitles = listOf(
            VodSubtitle("https://x/en.srt", "en", "English", "application/x-subrip"),
            VodSubtitle("https://x/pt.srt", "pt-BR", "Português", "application/x-subrip")
        )
        assertEquals(
            "pt-BR",
            VodSubtitleSupport.preferPortuguese(subtitles).first().language
        )
    }

    @Test
    fun buildsCommonsTimedTextVttUrl() {
        val url = WikimediaSubtitleSupport.timedTextUrl(
            "File:Krazy Kat Bugologist 1916 silent.ogv",
            "pt-br"
        )
        assertTrue(url.startsWith("https://commons.wikimedia.org/w/api.php"))
        assertTrue(url.contains("action=timedtext"))
        assertTrue(url.contains("trackformat=vtt"))
        assertTrue(url.contains("lang=pt-br"))
    }

    @Test
    fun detectsWebVttPayload() {
        assertTrue(
            WikimediaSubtitleSupport.looksLikeSubtitle(
                "WEBVTT\n\n00:00:01.000 --> 00:00:03.000\nOlá"
            )
        )
    }

    @Test
    fun rightsPolicyAcceptsPublicDomainAndCreativeCommons() {
        assertTrue(ArchiveRightsPolicy.isOpen("Public Domain", null))
        assertTrue(
            ArchiveRightsPolicy.isOpen(
                null,
                "https://creativecommons.org/licenses/by/4.0/"
            )
        )
    }
}

